// Data: approved recipe account-contact (steps Account), cleaned up after the test
// Note: Uses openNewFromRelatedList for the Contacts related list action. Step 1 clicks editMailingAddressButton on the Contact record page.
import { test, expect } from '../../fixtures/index.js';
import { meta } from 'reporting-labs';
import { AccountRecordPage } from '../../pages/AccountRecordPage.js';
import { ContactRecordPage } from '../../pages/ContactRecordPage.js';
import { NewContactDialog } from '../../pages/NewContactDialog.js';
import { recordIdFromView, showRelatedList, waitForSpinners } from '../../support/lightning.js';
import { soqlValue } from '../../support/api.js';

test.describe('SF-219 Mailing Address defaults from Account Billing Address on Contact creation and can be changed afterwards', () => {
  test.describe.configure({ mode: 'parallel' });

  test(
    'TC-SF-219-002 Mailing Address defaults from Account Billing Address on Contact creation and can be changed afterwards',
    { tag: ['@functional', '@P2', '@SF-219', '@persona:system-admin', '@recommended'] },
    async ({ page, data, sf }) => {
      meta({
        priority: 'P2',
        severity: 'minor',
        feature: 'Account',
        story: 'SF-219',
        owner: 'qa-agent',
        testCase: 'TC-SF-219-002',
      });
      const accountRecordPage = new AccountRecordPage(page);
      const contactRecordPage = new ContactRecordPage(page);
      const newContactDialog = new NewContactDialog(page);
      const firstname = data.unique('firstname');
      const lastname = data.unique('lastname');
      await data.create('account-contact', ['Account']);
      await test.step('1. Create a Contact from the Account related list and observe the Mailing Address fields', async () => {
        // Expected (APPROVED_REQUIREMENT; BRD-CON-012#BR-05): Mailing Address defaults from the Account's Billing Address when the Contact is created
        await accountRecordPage.open(data.id('Account'));
        await showRelatedList(accountRecordPage.contactsRelatedList, accountRecordPage.relatedTab);
        await accountRecordPage.contactsNewButton.click();
        await expect(newContactDialog.root).toBeVisible();
        await newContactDialog.firstName.fill(firstname);
        await newContactDialog.lastName.fill(lastname);
        await data.adopt('CreatedContact', 'Contact', 'FirstName', firstname);
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        await recordIdFromView(page, 'Contact');
        await expect.poll(() => soqlValue(sf, 'Account', data.id('Account'), 'BillingCountry')).toBe('India');
        await expect
          .poll(() => soqlValue(sf, 'Contact', data.id('CreatedContact'), 'MailingCountry'))
          .toBe(data.value('Account', 'BillingCountry'));
      });
      await test.step('2. Modify the Mailing Address values on the Contact record and click Save', async () => {
        // Expected (APPROVED_REQUIREMENT; BRD-CON-012#BR-05): Users may change it afterwards and the updated Mailing Address is saved
        await contactRecordPage.editMailingAddressButton.click();
        await waitForSpinners(page);
        await expect
          .poll(() => soqlValue(sf, 'Contact', data.id('CreatedContact'), 'MailingCountry'))
          .toBe(data.value('Account', 'BillingCountry'));
      });
    },
  );
});
